import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.DIWxYxwh.js";const b=JSON.parse('{"title":"vLLM 的显存、Block 与并发调度","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/vLLM 的显存、Block 与并发调度.md","filePath":"LLM推理/vLLM 的显存、Block 与并发调度.md","lastUpdated":1791972048000}'),n={name:"LLM推理/vLLM 的显存、Block 与并发调度.md"};function l(d,t,i,p,c,r){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="vllm-的显存、block-与并发调度" tabindex="-1">vLLM 的显存、Block 与并发调度 <a class="header-anchor" href="#vllm-的显存、block-与并发调度" aria-label="Permalink to &quot;vLLM 的显存、Block 与并发调度&quot;">​</a></h1><h2 id="一、显存怎么分-从总显存到-kv-block" tabindex="-1">一、显存怎么分：从总显存到 KV Block <a class="header-anchor" href="#一、显存怎么分-从总显存到-kv-block" aria-label="Permalink to &quot;一、显存怎么分：从总显存到 KV Block&quot;">​</a></h2><h3 id="_1-1-显存的三层拆分" tabindex="-1">1.1 显存的三层拆分 <a class="header-anchor" href="#_1-1-显存的三层拆分" aria-label="Permalink to &quot;1.1 显存的三层拆分&quot;">​</a></h3><p>vLLM 启动时，把 GPU 显存分成三块：</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>权重和非 torch</td><td>模型权重、CUDA context、框架固定开销</td></tr><tr><td>峰值激活</td><td>按 <code>max-model-len</code> 做 profile 时测得的最大中间激活</td></tr><tr><td>KV cache</td><td>剩下的全部给 KV block</td></tr></tbody></table><p><code>gpu-memory-utilization</code> 控制的是<strong>总预算</strong>。权重和激活先占，剩下的才给 KV：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总预算 = 可见显存 × gpu-memory-utilization</span></span>
<span class="line"><span>KV cache = 总预算 − 权重 − 激活</span></span></code></pre></div><p><strong>关键点</strong>：权重是固定的，激活由 <code>max-model-len</code> 和 <code>max-num-batched-tokens</code> 决定，只有 KV cache 是“弹性”的。调 <code>gpu-memory-utilization</code>，调的就是 KV 这块的大小。</p><h3 id="_1-2-kv-block-的大小" tabindex="-1">1.2 KV Block 的大小 <a class="header-anchor" href="#_1-2-kv-block-的大小" aria-label="Permalink to &quot;1.2 KV Block 的大小&quot;">​</a></h3><p>vLLM 用 PagedAttention 管理 KV cache，把 KV 切成固定大小的 <strong>block</strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><code>block_size</code></td><td>vLLM 默认 16 token</td></tr><tr><td>每个 block 存什么</td><td>16 个 token 的 K 和 V，覆盖所有全注意力层</td></tr><tr><td>每个 block 字节数</td><td><code>block_size × num_kv_heads × head_dim × 2(K和V) × dtype_bytes</code></td></tr><tr><td>block 数量</td><td><code>KV cache 字节数 / 每个 block 字节数</code></td></tr></tbody></table><p>每个 block 的物理布局：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[block_size, num_kv_heads, head_dim] × 2(K和V) × dtype_bytes</span></span></code></pre></div><p><strong>block 是 vLLM 管理 KV 的最小单位</strong>。一个请求的上下文在逻辑上是连续的 token 序列，但在物理显存里被切成多个 block，<strong>不要求连续</strong>。<code>block_table</code> 记录逻辑位置到物理 block 的映射。</p><h3 id="_1-3-block-的分配与增长" tabindex="-1">1.3 Block 的分配与增长 <a class="header-anchor" href="#_1-3-block-的分配与增长" aria-label="Permalink to &quot;1.3 Block 的分配与增长&quot;">​</a></h3><p>一个请求的 block 不是一次性全分配的，而是<strong>按需分配</strong>：</p><ul><li><strong>Prefill 阶段</strong>：prompt 的所有 token 的 KV 写入。<code>ceil(prompt_len / block_size)</code> 个 block。</li><li><strong>Decode 阶段</strong>：每生成一个 token，写一个 token 的 KV。当前 block 满了，就分配一个新 block。</li></ul><p>请求结束后，它引用的所有 block 被释放。如果开启了 Prefix Cache，<code>ref_cnt</code> 归 0 的 block 不一定立即清空，可能留在池子里等复用。</p><h3 id="_1-4-显存容量和上下文长度的关系" tabindex="-1">1.4 显存容量和上下文长度的关系 <a class="header-anchor" href="#_1-4-显存容量和上下文长度的关系" aria-label="Permalink to &quot;1.4 显存容量和上下文长度的关系&quot;">​</a></h3><p>KV 容量决定了能同时容纳多少 token 的上下文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能放下的请求数 = KV token 容量 / 单条请求占用的 token 数</span></span>
<span class="line"><span>单条请求占用的 token 数 ≈ 输入长度 + 输出长度</span></span></code></pre></div><p><strong>放得下不等于能开到那么多</strong>。短请求先被算力限制，长请求才被显存限制。</p><hr><h2 id="二、并发时调度器怎么跑" tabindex="-1">二、并发时调度器怎么跑 <a class="header-anchor" href="#二、并发时调度器怎么跑" aria-label="Permalink to &quot;二、并发时调度器怎么跑&quot;">​</a></h2><h3 id="_2-1-调度器的四个约束" tabindex="-1">2.1 调度器的四个约束 <a class="header-anchor" href="#_2-1-调度器的四个约束" aria-label="Permalink to &quot;2.1 调度器的四个约束&quot;">​</a></h3><p>每一步前向，调度器要决定“这一步算哪些 token”。它受四个约束：</p><table tabindex="0"><thead><tr><th>约束</th><th>含义</th></tr></thead><tbody><tr><td><code>max_num_batched_tokens</code></td><td>一步最多算多少 token</td></tr><tr><td><code>max_num_seqs</code></td><td>一步最多同时处理多少条请求</td></tr><tr><td><code>max_model_len</code></td><td>单条请求输入加输出的上限</td></tr><tr><td>空闲 block 数</td><td>KV 容量决定的硬上限</td></tr></tbody></table><p><strong>这四个约束里，哪个先撞上，哪个就是当前瓶颈。</strong></p><h3 id="_2-2-每一步调度做什么" tabindex="-1">2.2 每一步调度做什么 <a class="header-anchor" href="#_2-2-每一步调度做什么" aria-label="Permalink to &quot;2.2 每一步调度做什么&quot;">​</a></h3><p>调度器的核心任务可以概括成一句话：</p><blockquote><p><strong>让每个请求的 <code>num_computed_tokens</code> 追上它的 <code>num_tokens</code>。</strong></p></blockquote><ul><li><code>num_tokens</code>：这条请求总共要算多少 token（prompt + 已生成）</li><li><code>num_computed_tokens</code>：已经算过多少 token</li></ul><p>每一步，调度器从所有待处理请求里选一批，凑不超过 <code>max_num_batched_tokens</code> 的 token 数，执行一次前向。</p><p><strong>优先级</strong>：</p><ol><li><strong>正在 decode 的请求优先</strong>。它们每步只贡献 1 个 token，必须让它们持续出字，否则 ITL 会爆炸。</li><li><strong>剩余预算给 prefill</strong>。新请求的 prompt 被切成 chunk，填满剩余预算。</li></ol><h3 id="_2-3-调度流程总结" tabindex="-1">2.3 调度流程总结 <a class="header-anchor" href="#_2-3-调度流程总结" aria-label="Permalink to &quot;2.3 调度流程总结&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每一步：</span></span>
<span class="line"><span>  1. 优先调度正在 decode 的请求，每条 1 token</span></span>
<span class="line"><span>  2. 剩余预算 = max_num_batched_tokens − decode token 数</span></span>
<span class="line"><span>  3. 从待 prefill 请求里选，凑不超过剩余预算</span></span>
<span class="line"><span>  4. 执行一次前向</span></span>
<span class="line"><span>  5. 更新 num_computed_tokens</span></span>
<span class="line"><span>  6. 满了的请求退出，新请求进来</span></span></code></pre></div><h3 id="_2-4-并发升高时发生什么" tabindex="-1">2.4 并发升高时发生什么 <a class="header-anchor" href="#_2-4-并发升高时发生什么" aria-label="Permalink to &quot;2.4 并发升高时发生什么&quot;">​</a></h3><p>随着并发升高，会发生三件事：</p><ol><li><strong>同一步里的 prefill token 变多</strong>。<code>C × L</code> 增大，prefill 计算量增大，TTFT 变长。</li><li><strong><code>C × L</code> 越过 <code>max_num_batched_tokens</code> 后，prompt 被切</strong>。部分请求的 prefill 被拆成多步，TTFT 额外增加排队时间。</li><li><strong>decode 请求和 prefill 争预算</strong>。prefill chunk 占用预算时，decode 请求要等这一步结束才有下一个 token，ITL 出现尖峰。</li></ol><hr><h2 id="三、ttft-由什么决定" tabindex="-1">三、TTFT 由什么决定 <a class="header-anchor" href="#三、ttft-由什么决定" aria-label="Permalink to &quot;三、TTFT 由什么决定&quot;">​</a></h2><h3 id="_3-1-ttft-的三段构成" tabindex="-1">3.1 TTFT 的三段构成 <a class="header-anchor" href="#_3-1-ttft-的三段构成" aria-label="Permalink to &quot;3.1 TTFT 的三段构成&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TTFT = 排队等待 + prefill 计算 + 首 token 采样</span></span></code></pre></div><ul><li><strong>排队等待</strong>：请求到了，但这一步预算已被别人占了，要等下一步。</li><li><strong>prefill 计算</strong>：prompt 过一遍模型，算出 KV。这是 TTFT 的大头。</li><li><strong>首 token 采样</strong>：prefill 完，出第一个 token 的时间，通常很小。</li></ul><p>在无排队、无缓存命中的情况下，TTFT 基本就是 prefill 计算时间。prefill 计算时间和 <strong>prompt token 数</strong>近似成正比。</p><h3 id="_3-2-ttft-的近似公式" tabindex="-1">3.2 TTFT 的近似公式 <a class="header-anchor" href="#_3-2-ttft-的近似公式" aria-label="Permalink to &quot;3.2 TTFT 的近似公式&quot;">​</a></h3><p>设：</p><ul><li>单条 prompt 长度 <code>L</code></li><li>并发 <code>C</code></li><li>每步 token 预算 <code>B</code>（<code>max_num_batched_tokens</code>）</li></ul><p><strong>情况一：<code>C × L ≤ B</code></strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prefill token 数 ≈ C × L</span></span>
<span class="line"><span>TTFT ≈ T_固定 + f(C × L)</span></span></code></pre></div><p><code>f</code> 是 prefill 时间函数，近似线性，斜率随 token 数增大略降。</p><p><strong>情况二：<code>C × L &gt; B</code></strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prefill 步数 ≈ ceil(C × L / B)</span></span>
<span class="line"><span>TTFT ≈ T_固定 + prefill 步数 × f(B) + 排队等待</span></span></code></pre></div><p><strong>TTFT 取决于两件事</strong>：</p><ol><li>同一步里塞了多少 prefill token（由 <code>C × L</code> 和 <code>B</code> 共同决定）。</li><li>要切几步（由 <code>C × L / B</code> 决定）。</li></ol><h3 id="_3-3-短提示词为什么-ttft-基本不变" tabindex="-1">3.3 短提示词为什么 TTFT 基本不变 <a class="header-anchor" href="#_3-3-短提示词为什么-ttft-基本不变" aria-label="Permalink to &quot;3.3 短提示词为什么 TTFT 基本不变&quot;">​</a></h3><p>假设 prompt 只有 50 token：</p><ul><li>并发 1：prefill 50 token。</li><li>并发 2：prefill 100 token。</li><li>并发 4：prefill 200 token。</li></ul><p><strong>100 token、200 token 的 prefill 只有几毫秒到十几毫秒。</strong> 在 TTFT 的几百毫秒里，prefill 只占很小一块，剩下的是固定开销（调度、采样、框架、网络）。<strong>固定开销不随并发变，所以 TTFT 基本不变。</strong></p><p>而 536 token 的 prompt，prefill 本身就是几百毫秒，翻倍就是几百毫秒的差别。</p><p><strong>关键不是“并发几条”，而是“这几条加起来多少 prefill token”。</strong></p><h3 id="_3-4-一个更精确的写法" tabindex="-1">3.4 一个更精确的写法 <a class="header-anchor" href="#_3-4-一个更精确的写法" aria-label="Permalink to &quot;3.4 一个更精确的写法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TTFT ≈ T_固定 + T_prefill(C × L 或 B)</span></span></code></pre></div><ul><li><code>T_固定</code>：调度、采样、框架、网络等，不随 token 数变。</li><li><code>T_prefill</code>：prefill 计算，随同一步 token 数增长。</li></ul><p><strong>短 prompt 时，<code>T_prefill</code> 远小于 <code>T_固定</code>，TTFT 看起来不变。</strong><strong>长 prompt 时，<code>T_prefill</code> 是主要部分，TTFT 随 token 数明显增长。</strong></p><h3 id="_3-5-调-max-num-batched-tokens-对-ttft-的影响" tabindex="-1">3.5 调 <code>max-num-batched-tokens</code> 对 TTFT 的影响 <a class="header-anchor" href="#_3-5-调-max-num-batched-tokens-对-ttft-的影响" aria-label="Permalink to &quot;3.5 调 \`max-num-batched-tokens\` 对 TTFT 的影响&quot;">​</a></h3><p><code>B</code> 越大，<code>C × L ≤ B</code> 能容纳的并发越高，prompt 被切的概率越低，TTFT 越可控。</p><p><strong>代价</strong>：每一步的 prefill 占用 GPU 更久，如果同时有 decode 请求在跑，它们的 ITL 尖峰会更宽。启动时按这个上限做显存 profile，激活占得更多，KV 容量可能下降。</p><hr><h2 id="四、示例-一个-27b-稠密模型在-48gb-卡上的完整推演" tabindex="-1">四、示例：一个 27B 稠密模型在 48GB 卡上的完整推演 <a class="header-anchor" href="#四、示例-一个-27b-稠密模型在-48gb-卡上的完整推演" aria-label="Permalink to &quot;四、示例：一个 27B 稠密模型在 48GB 卡上的完整推演&quot;">​</a></h2><p>下面用一个具体例子，把上面的概念串起来。示例参数如下，<strong>不是任何一次真实测试的结果，只是用来演示计算方式</strong>。</p><h3 id="_4-1-示例配置" tabindex="-1">4.1 示例配置 <a class="header-anchor" href="#_4-1-示例配置" aria-label="Permalink to &quot;4.1 示例配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模型</td><td>27B 稠密模型，FP8 权重</td></tr><tr><td>GPU</td><td>48GB，可见显存 47.36 GiB</td></tr><tr><td>显存带宽</td><td>1008 GB/s</td></tr><tr><td><code>gpu-memory-utilization</code></td><td>0.9</td></tr><tr><td><code>block_size</code></td><td>16</td></tr><tr><td><code>max_num_batched_tokens</code></td><td>2048</td></tr><tr><td><code>max_num_seqs</code></td><td>256</td></tr><tr><td><code>max_model_len</code></td><td>20480</td></tr><tr><td>KV dtype</td><td>FP8</td></tr><tr><td>每 token KV 字节数</td><td>假设 49 KiB</td></tr><tr><td>权重和非 torch</td><td>假设 29.34 GiB</td></tr><tr><td>峰值激活</td><td>假设 2.06 GiB</td></tr></tbody></table><h3 id="_4-2-显存拆分计算" tabindex="-1">4.2 显存拆分计算 <a class="header-anchor" href="#_4-2-显存拆分计算" aria-label="Permalink to &quot;4.2 显存拆分计算&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总预算 = 47.36 × 0.9 = 42.63 GiB</span></span>
<span class="line"><span>KV cache = 42.63 − 29.34 − 2.06 = 11.23 GiB</span></span></code></pre></div><p>KV token 容量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>11.23 GiB / 49 KiB ≈ 239,000 token</span></span></code></pre></div><p>Block 数量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>239,000 / 16 ≈ 14,900 个 block</span></span></code></pre></div><p>每个 block 字节数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>49 KiB × 16 ≈ 784 KiB</span></span></code></pre></div><h3 id="_4-3-并发容量计算" tabindex="-1">4.3 并发容量计算 <a class="header-anchor" href="#_4-3-并发容量计算" aria-label="Permalink to &quot;4.3 并发容量计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>单条长度</th><th>放得下</th></tr></thead><tbody><tr><td>664（536 输入 + 128 输出）</td><td>239,000 / 664 ≈ 360 路</td></tr><tr><td>2,048</td><td>239,000 / 2,048 ≈ 117 路</td></tr><tr><td>8,192</td><td>239,000 / 8,192 ≈ 29 路</td></tr><tr><td>20,480</td><td>239,000 / 20,480 ≈ 11.7 路</td></tr></tbody></table><h3 id="_4-4-ttft-推演" tabindex="-1">4.4 TTFT 推演 <a class="header-anchor" href="#_4-4-ttft-推演" aria-label="Permalink to &quot;4.4 TTFT 推演&quot;">​</a></h3><p>假设单条 prompt 536 token，prefill 时间函数 <code>f(n) ≈ n × 0.5 ms</code>（仅用于演示）。</p><p><strong>并发 1</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C × L = 536 ≤ 2048，一步算完</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 536 × 0.5 ms = T_固定 + 268 ms</span></span></code></pre></div><p><strong>并发 2</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C × L = 1072 ≤ 2048，一步算完</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 1072 × 0.5 ms = T_固定 + 536 ms</span></span></code></pre></div><p>TTFT 约为并发 1 的 1.8 倍。</p><p><strong>并发 4</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C × L = 2144 &gt; 2048，被切</span></span>
<span class="line"><span>prefill 步数 = ceil(2144 / 2048) = 2</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 2 × f(2048) + 排队</span></span>
<span class="line"><span>     ≈ T_固定 + 2 × 1024 ms + 排队</span></span>
<span class="line"><span>     ≈ T_固定 + 2048 ms + 排队</span></span></code></pre></div><p>第 4 条被切，TTFT 额外增加一步的排队时间。</p><p><strong>并发 8</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C × L = 4288 &gt; 2048</span></span>
<span class="line"><span>prefill 步数 = ceil(4288 / 2048) = 3</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 3 × 1024 ms + 排队</span></span></code></pre></div><p><strong>并发 16</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C × L = 8576 &gt; 2048</span></span>
<span class="line"><span>prefill 步数 = ceil(8576 / 2048) = 5</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 5 × 1024 ms + 排队</span></span></code></pre></div><h3 id="_4-5-结论" tabindex="-1">4.5 结论 <a class="header-anchor" href="#_4-5-结论" aria-label="Permalink to &quot;4.5 结论&quot;">​</a></h3><p>从这个示例可以看出：</p><ol><li><strong>KV 容量决定能放多少路</strong>。本例约 360 路（664 token 请求），但实际远开不到，因为算力先限制。</li><li><strong>TTFT 由 <code>C × L</code> 和 <code>B</code> 决定</strong>。<code>C × L ≤ B</code> 时一步算完，TTFT 随 <code>C × L</code> 线性增长；<code>C × L &gt; B</code> 时被切成多步，TTFT 额外增加排队。</li><li><strong>并发 4 是一个转折点</strong>。536 × 4 = 2144 刚好越过 2048，第 4 条被切，TTFT 从“线性增长”变成“多一步排队”。</li><li><strong>调大 <code>B</code> 可以推迟转折点</strong>。<code>B = 4096</code> 时，并发 4 的 <code>C × L = 2144 &lt; 4096</code>，四条整步进，TTFT 回到线性增长。</li><li><strong>代价是 ITL 尖峰变宽</strong>。<code>B</code> 越大，每一步的 prefill 占用 GPU 越久，decode 请求等得越久。</li></ol><hr><h2 id="五、一句话总结" tabindex="-1">五、一句话总结 <a class="header-anchor" href="#五、一句话总结" aria-label="Permalink to &quot;五、一句话总结&quot;">​</a></h2><p><strong>vLLM 把显存分成权重、激活、KV cache 三块，KV cache 切成 16 token 一个的 block。调度器每一步在 <code>max_num_batched_tokens</code>、<code>max_num_seqs</code>、<code>max_model_len</code>、空闲 block 数四个约束下，优先调度 decode 请求，剩余预算给 prefill。TTFT 由同一步里的 prefill token 总数决定，不是由并发数决定：<code>C × L ≤ B</code> 时一步算完，<code>C × L &gt; B</code> 时被切成多步，TTFT 额外增加排队。</strong></p>`,104)])])}const g=e(n,[["render",l]]);export{b as __pageData,g as default};
